# all placements of O and L triomino in cells
shapes=[{(0,0),(0,1),(1,0),(1,1)}]
# L triomino variants from 2x2 missing one
shapes += [{(r,c) for r in range(2) for c in range(2) if (r,c)!=(mr,mc)} for mr in range(2) for mc in range(2)]
placements=[]
for si,shape in enumerate(shapes):
  h=max(r for r,c in shape)+1; w=max(c for r,c in shape)+1
  for dr in range(7-h):
    for dc in range(7-w):
      p=frozenset((r+dr,c+dc) for r,c in shape)
      if p<=cells: placements.append((si,p))
from collections import defaultdict
bycell=defaultdict(list)
for ix,(si,p) in enumerate(placements):
 for cell in p: bycell[cell].append(ix)
sol=[]
def rec(rem, chosen):
 if not rem:
  sol.append(chosen[:]); return
 cell=min(rem,key=lambda c:sum(placements[ix][1]<=rem for ix in bycell[c]))
 for ix in bycell[cell]:
  si,p=placements[ix]
  if p<=rem:
   rec(rem-p,chosen+[(si,p)])
rec(cells,[])
len(sol), {tuple(sorted([si for si,p in s])) for s in sol}
